  ["Activos esta semana"] = "Active this week",
  ["Administración"] = "Administration",
  ["Administración enseña cómo va la conexión, con una prueba de mensajes."] = "Administration shows how the connection is doing, with a message test.",
  ["Administración: al cambiar de idioma ya no sale «Una acción de interfaz ha fallado por culpa de un accesorio». El juego no deja que un accesorio recargue la interfaz: escribe /reload."] = "Administration: changing the language no longer shows «Interface action failed because of an AddOn». The game does not let an addon reload the interface: type /reload.",
  ["Ahora no"] = "Not now",
  ["Ahora no hay nadie más de la hermandad conectado. Cuando haya alguien, sale aquí; si tiene BlazonGuild, con «Retar»."] = "There is nobody else from the guild online now. When there is, they show here; with BlazonGuild, with «Challenge».",
  ["Ahora no puede"] = "Can't right now",
  ["Ahora organizas en %s"] = "You now organise in %s",
  ["Ahora pulsa dónde va %s: un grupo, «Sin grupo» o «Reserva». Si pulsas a otro jugador, se cambian el sitio."] = "Now click where %s goes: a group, «No group» or «Reserve». If you click another player, they swap places.",
  ["Ahora tienen %s conectados, %s con BlazonGuild."] = "They now have %s online, %s with BlazonGuild.",
  ["Ahora: %d %s y %d %s."] = "Now: %d %s and %d %s.",
  ["Ajustes del maestro"] = "Guild master's settings",
  ["Al abrir el mapa del mundo la ventana se minimiza sola, y vuelve al cerrarlo."] = "When you open the world map the window minimises by itself, and comes back when you close it.",
  ["Al hablar con un posadero, un aviso te propone una partida. Todo por puntos: aquí no se mueve oro."] = "When you talk to an innkeeper, a notice offers you a game. All for points: no gold moves here.",
  ["Al sortear, los mejores de la Arena son cabezas de serie; el resto se sortea con /roll, que veréis en el chat."] = "When drawing, the best of the Arena are seeded; the rest are drawn with /roll, which you'll see in the chat.",
  ["Al terminar, quien la dirigió escribe cómo fue. Queda en la crónica de la hermandad con quién estuvo."] = "When it ends, whoever led it writes how it went. It stays in the guild's chronicle with who was there.",
  ["Al terminar, quien la dirigió escribe el parte, que queda en la crónica."] = "When it ends, whoever led it writes the report, which stays in the chronicle.",
  ["Alguien"] = "Someone",
  ["Alianza"] = "Alliance",
  ["Alianza creada"] = "Alliance created",
  ["Alianza «%s»"] = "Alliance «%s»",
  ["Alianza, pestaña «Cartas y avisos»: cartas del líder a los maestros (con quién las ha leído), «puertas abiertas» para mandar a los nuevos a una hermandad y ocultar a alguien en los chats comunes."] = "Alliance, «Letters and notices» tab: the leader's letters to the masters (with who has read them), «open doors» to send newcomers to one guild, and hiding someone in the shared chats.",
  ["Alter de %s"] = "Alt of %s",
