  ["Apuntarme"] = "Sign me up",
  ["Aquí no hay capas: estás en una mazmorra, en un barco o volando."] = "There are no layers here: you are in a dungeon, on a boat or flying.",
  ["Aquí no hay zona: estás en una mazmorra, en un barco o volando."] = "There's no zone here: you're in a dungeon, on a boat or flying.",
  ["Aquí tendréis una pestaña por cada hermandad hermana."] = "Here you'll have a tab for each sister guild.",
  ["Arena"] = "Arena",
  ["Arena, nueva pestaña «Taberna»: los Huesos, un juego de dados por puntos (contra la casa para practicar, o contra alguien de la hermandad)."] = "Arena, new «Tavern» tab: Bones, a dice game for points (against the house to practise, or against someone in the guild).",
  ["Arena, nueva pestaña «Torneos»: torneos con cuadro eliminatorio y sorteo con /roll, y veladas con combates anunciados."] = "Arena, new «Tournaments» tab: knockout tournaments with a /roll draw, and fight nights with announced bouts.",
  ["Arena, «Cara a cara»: dos luchadores frente a frente (puntos, rango, récord, sus combates entre ellos), con su vida en directo si los tienes cerca y quién gana al acabar. Se agranda para retransmitir."] = "Arena, «Face to face»: two fighters side by side (points, rank, record, their bouts against each other), with their health live if they are near you and the winner at the end. It grows bigger for streaming.",
  ["Arena: %s"] = "Arena: %s",
  ["Arena: en «Retos» salen todos los conectados, y se explica cómo retar. Administración: solo marca en rojo los errores de esta versión."] = "Arena: «Challenges» shows everyone online and explains how to challenge. Administration: only this version's errors are marked in red.",
  ["Armería"] = "Armory",
  ["Armería: cada objeto sale con su nombre y su icono (antes salía «Objeto 6189» con una interrogación). En tu propio equipo, la ventana del objeto ya no sale repetida al lado."] = "Armory: every item shows its name and icon (it used to say «Item 6189» with a question mark). On your own gear, the item's window no longer appears twice side by side.",
  ["Armería: la lista del equipo ya no se sale de su panel la primera vez que se abre."] = "Armory: the gear list no longer spills out of its panel the first time it opens.",
  ["Armería: «Ver su equipo» funciona aunque esté lejos (si tiene BlazonGuild, se lo pedimos). Y en los encargos puedes poner el objeto con Mayús+clic o arrastrándolo."] = "Armory: «See their gear» works even when they're far away (if they have BlazonGuild, we ask them). And in orders you can put the item with Shift+click or by dragging it.",
  ["Arrastra aquí a quien quede de reserva."] = "Drag here whoever stays in reserve.",
  ["Arrastra cada nombre a su grupo y su fila, o púlsalo y luego pulsa dónde va. Al soltarlo sobre otro, se cambian el sitio."] = "Drag each name to its group and row, or click it and then click where it goes. Dropping it on someone swaps them.",
  ["Arreglado: Artesanía y botín se veía con las pestañas una encima de otra."] = "Fixed: Crafting and loot showed its tabs one on top of the other.",
  ["Arreglado: al volver a programar una raid cancelada, seguía cancelada."] = "Fixed: rescheduling a cancelled raid left it cancelled.",
  ["Arreglado: la Arena y «Se busca» se quedaban a medias (y la Arena enseñaba «Nueva temporada» a todos)."] = "Fixed: the Arena and «Wanted» stopped halfway (and the Arena showed «New season» to everyone).",
  ["Arrástralo a un grupo, o púlsalo y luego pulsa dónde va. Clic derecho: sin grupo."] = "Drag it to a group, or click it and then click where it goes. Right click: no group.",
  ["Arrástralo para moverlo por el borde del minimapa. /bg minimapa lo oculta."] = "Drag it to move it around the edge of the minimap. /bg minimapa hides it.",
  ["Artesanos"] = "Crafters",
  ["Artesanos de la hermandad"] = "Guild crafters",
  ["Artesanía y botín"] = "Crafting and loot",
  ["Asalto"] = "Assault",
  ["Asunto"] = "Subject",
  ["Así funciona Artesanía y botín"] = "How Crafting and loot works",
  ["Así funciona el Mapa"] = "How the Map works",
  ["Así funciona el Reclutamiento"] = "How Recruitment works",
  ["Así funciona la Alianza"] = "How the Alliance works",
  ["Así funciona la Arena"] = "How the Arena works",
  ["Así funciona la Sala de guerra"] = "How the War room works",
  ["Así funciona la Tesorería"] = "How the Treasury works",
  ["Así funciona «Se busca»"] = "How «Wanted» works",
  ["Así funcionan las Raids"] = "How Raids work",
  ["Así funcionan los honores"] = "How honours work",
  ["Así tu hermandad te ve en la Armería aunque estéis lejos: lo que llevas puesto y su nivel, lo mismo que ve quien te inspecciona en el juego."] = "That way your guild sees you in the Armory even when you're far apart: what you wear and its level, the same as anyone who inspects you in the game.",
  ["Ausente"] = "Away",
  ["Automático (el del juego)"] = "Automatic (the game's)",
  ["Autoprueba"] = "Self-test",
  ["Autoprueba (Administración o /bg autoprueba): comprueba el addon en tu juego y te da un informe para copiar."] = "Self-test (Administration or /bg autoprueba): checks the addon in your game and gives you a report to copy.",
  ["Avisamos a %s. En cuanto contesten, estaréis dentro."] = "We've told %s. As soon as they answer, you'll be in.",
  ["Avisamos a todos los llamados de que no se hace."] = "We'll tell everyone called that it's off.",
  ["Aviso final"] = "Final warning",
  ["Avisos %s"] = "Warnings %s",
  ["Avisos acumulados: %s de 3. Al tercero se abre un caso que decide el maestro."] = "Warnings so far: %s of 3. On the third, a case is opened for the guild master to decide.",
  ["Avistamiento: %s"] = "Sighting: %s",
