  ["Banda (opcional)"] = "Raid (optional)",
  ["Banda de %s desde el nivel %s. En la hermandad tienen el nivel %s (%s conectados ahora).%s"] = "A raid of %s from level %s. In the guild, %s have the level (%s online now).%s",
  ["Banda o actividad"] = "Raid or activity",
