  ["Bastión Krol'dok"] = "Krol'dok Stronghold",
  ["Batíos en duelo desde el juego (clic derecho en su retrato, «Duelo»). Al terminar, el juego dice quién ganó, y el addon de quien pierde lo apunta solo."] = "Duel from the game (right click on their portrait, «Duel»). When it ends, the game says who won, and the loser's addon records it by itself.",
  ["BlazonGuild %s; juego %s, interfaz %s"] = "BlazonGuild %s; game %s, interface %s",
  ["BlazonGuild deja de tocar los menús, las placas y el chat del juego. Su ventana sigue igual."] = "BlazonGuild stops touching the game's menus, nameplates and chat. Its window stays the same.",
  ["BlazonGuild funciona entre los addons de los miembros de tu hermandad. Para eso, tu addon tiene que mandar algunos datos a los de tus compañeros. Si aceptas, esto es lo que se comparte:"] = "BlazonGuild works between the addons of your guild's members. For that, your addon has to send some data to your companions'. If you accept, this is what is shared:",
  ["BlazonGuild habla ahora inglés, alemán, francés, italiano, portugués y ruso, además de español."] = "BlazonGuild now speaks English, German, French, Italian, Portuguese and Russian, as well as Spanish.",
  ["BlazonGuild vuelve a poner sus marcas y sus líneas en la interfaz del juego."] = "BlazonGuild puts its marks and lines back in the game's interface.",
  ["BlazonGuild — autoprueba %s"] = "BlazonGuild — self-test %s",
