  ["Entras en el grupo de %s para %s. Te llegará su invitación."] = "You join %s's group for %s. Their invitation will reach you.",
  ["Entre ellos: %d-%d"] = "Head to head: %d-%d",
  ["Enviada a %s. Te avisamos cuando llegue."] = "Sent to %s. We'll tell you when it arrives.",
