  ["La Taberna"] = "The Tavern",
  ["La alianza cuenta personas, no personajes: los alters cuentan una vez."] = "The alliance counts people, not characters: alts count once.",
  ["La alianza estaba cambiando en ese momento. Prueba otra vez."] = "The alliance was changing at that moment. Try again.",
  ["La alianza manda ahora a los nuevos a «%s», hasta las %s."] = "The alliance now sends newcomers to «%s», until %s.",
  ["La alianza recibe una clave nueva, para que no puedan seguir escribiendo."] = "The alliance gets a new key, so they can't keep writing.",
  ["La alianza tiene líder: el maestro de la hermandad que vote la mayoría de los maestros."] = "The alliance has a leader: the master of the guild voted by most of the masters.",
  ["La alianza ya tiene diez hermandades."] = "The alliance already has ten guilds.",
  ["La alianza ya usa la clave nueva."] = "The alliance already uses the new key.",
  ["La banda ya estaba como en el plan."] = "The raid was already as in the plan.",
  ["La carta: qué quieres decir a los maestros"] = "The letter: what you want to tell the masters",
  ["La casa"] = "The house",
  ["La crean y la aceptan los maestros: ninguna hermandad entra sin que su maestro diga que sí."] = "The masters create it and accept it: no guild joins unless its master says yes.",
  ["La crónica empieza ahora: entradas, salidas, ascensos, raids y decisiones, según tu addon las ve."] = "The chronicle starts now: joins, departures, promotions, raids and decisions, as your addon sees them.",
  ["La cuota semanal"] = "The weekly dues",
  ["La deciden los maestros"] = "The masters decide",
  ["La escuadra está llena (15 con el jefe)."] = "The squad is full (15 with the leader).",
  ["La guía sale sola la primera vez que abres Artesanía, Mapa, Alianza o Sala de guerra."] = "The guide shows by itself the first time you open Crafting, Map, Alliance or War room.",
  ["La han recibido %s organizadores conectados."] = "Received by %s organisers online.",
  ["La hermandad"] = "The guild",
  ["La hermandad de %s ya está en una alianza."] = "%s's guild is already in an alliance.",
  ["La hermandad no sale en la clasificación: lo decide el maestro. "] = "The guild is not in the ranking: the guild master decides. ",
  ["La hermandad no sale: pulsa para publicar sus cifras (nada de nadie en concreto). "] = "The guild is not shown: click to publish its numbers (nothing about anyone in particular). ",
  ["La hermandad que lidera escribe cartas a los maestros, dice a qué hermandad van los nuevos y puede ocultar a alguien en los chats comunes. Y en la Sala de guerra, sus operaciones llegan a todas."] = "The leading guild writes letters to the masters, says which guild newcomers go to and can hide someone in the shared chats. And in the War room, its operations reach every guild.",
  ["La hermandad que lidera la alianza planea la operación en su Sala de guerra eligiendo «Toda la alianza». Llega a la Sala de guerra de cada hermandad; cada uno responde allí y el líder ve cuántos van de cada una."] = "The guild that leads the alliance plans the operation in its War room choosing «Whole alliance». It reaches every guild's War room; each one answers there and the leader sees how many go from each.",
  ["La línea de BlazonGuild en el recuadro de un jugador"] = "The BlazonGuild line in a player's tooltip",
  ["La mejor puntuación de la Arena de la hermandad."] = "The guild's best Arena rating.",
  ["La mejor puntuación de la Arena esta temporada, con 5 combates o más."] = "The best Arena rating this season, with 5 bouts or more.",
  ["La prueba no ha vuelto"] = "The test didn't come back",
  ["La puntuación"] = "The rating",
  ["La sala de este evento de la Arena, para quien lucha y quien mira. Se cierra una semana después de crearlo."] = "The room of this Arena event, for those who fight and those who watch. It closes a week after it was created.",
  ["La semana pasada: "] = "Last week: ",
  ["La temporada %s se cierra y se guarda con su campeón y su podio."] = "Season %s closes and is kept with its champion and its podium.",
  ["La ventana de BlazonGuild, sus diálogos y sus avisos"] = "BlazonGuild's window, its dialogs and its notices",
  ["La ventana «Cara a cara»"] = "The «Face to face» window",
  ["Las Mazmorras"] = "The Stockade",
  ["Las Minas de la Muerte"] = "The Deadmines",
  ["Las capas"] = "The layers",
  ["Las cartas del líder de la alianza son para los maestros y los capitanes de cada hermandad."] = "The alliance leader's letters are for the masters and captains of each guild.",
  ["Las decisiones finales de moderación siguen siendo del maestro."] = "The final moderation decisions are still the guild master's.",
  ["Las demás hermandades ya lo saben."] = "The other guilds already know.",
  ["Las hermandades de vuestra facción que juegan con BlazonGuild y publican sus cifras. Se conocen al jugar en grupo con alguien de ellas."] = "The guilds of your faction that play with BlazonGuild and publish their numbers. You meet them by playing in a group with someone of theirs.",
  ["Las hermandades la reciben solas; durante un minuto puede perderse algún mensaje."] = "The guilds get it by themselves; for a minute some message may be lost.",
  ["Las inscripciones ya están cerradas."] = "Sign-ups are already closed.",
  ["Las listas para elegir a alguien ya no salen vacías: se hacen al abrirlas, y si no hay nadie lo dicen."] = "The lists to choose someone no longer open empty: they're made when they open, and if there's nobody they say so.",
  ["Las marcas"] = "The marks",
  ["Las marcas sobre las placas de nombre y el aro del retrato del objetivo"] = "The marks over nameplates and the ring on the target's portrait",
  ["Las mazmorras de dentro de una capital son de su bando; las demás, para todos (las Minas de la Muerte y el Castillo de Colmillo Oscuro ya salen a las dos facciones)."] = "Dungeons inside a capital belong to its faction; the rest are for everyone (The Deadmines and Shadowfang Keep now show for both factions).",
  ["Las mazmorras y bandas son ya las de WoW Forever: sus 9 mazmorras nuevas (Salón de los Feudales, Ruinas de Lordaeron, Ciudad de Dalaran, Bastión Faucenegra…) y sus tres bandas, Cavernas del Túmulo, Cima Hyjal y Guarida de Onyxia, con los nombres del juego."] = "Dungeons and raids are now WoW Forever's: its 9 new dungeons (Hall of Thanes, Ruins of Lordaeron, City of Dalaran, Blackmaw Hold…) and its three raids, The Barrow Deeps, Hyjal Summit and Onyxia's Lair, with the game's names.",
  ["Las otras hermandades aún no han dicho cuántos van."] = "The other guilds haven't said yet how many are going.",
  ["Las otras hermandades no te verán conectado. Los mensajes de «Maestros» de otras hermandades no te llegarán mientras sigas oculto."] = "The other guilds won't see you online. «Masters» messages from other guilds won't reach you while you stay hidden.",
  ["Las otras hermandades vuelven a verte conectado."] = "The other guilds see you online again.",
  ["Las próximas dos semanas"] = "The next two weeks",
  ["Las próximas dos semanas (%s)"] = "The next two weeks (%s)",
  ["Las raids se comparten entre los addons de tu hermandad. Para crearlas, verlas y apuntarte, acepta antes la privacidad."] = "Raids are shared between your guild's addons. To create them, see them and sign up, accept the privacy first.",
  ["Las salas de roles y el comercio se comparten con todas."] = "The role rooms and trade are shared with all of them.",
  ["Le hemos preguntado si lo comparte; esperando su respuesta."] = "We asked whether they share it; waiting for the answer.",
  ["Le toca a %s%s"] = "It's %s's turn%s",
  ["Le toca a %s…"] = "It's %s's turn…",
  ["Levantar bandera"] = "Raise flag",
  ["Libro"] = "Ledger",
  ["Libro de la tesorería"] = "Treasury ledger",
  ["Libro para todos: %s"] = "Ledger for everyone: %s",
  ["Liderazgo"] = "Leadership",
  ["Llamada a los oficiales"] = "Call to the officers",
  ["Llamar a los oficiales"] = "Call the officers",
  ["Llegó a través de %s. «Invitar» manda la invitación del juego; «No» se lo dice con educación."] = "It came through %s. «Invite» sends the game's invitation; «No» tells them politely.",
  ["Lleva un tabardo."] = "Wears a tabard.",
  ["Lo apuntó el addon de %s, que perdió: solo quien pierde apunta el combate, para que nadie se dé victorias."] = "Recorded by the addon of %s, who lost: only the loser records the bout, so that nobody gives themselves wins.",
  ["Lo comparte él mismo (%s)."] = "They share it themselves (%s).",
  ["Lo comparte: ya lo ves aunque esté lejos."] = "They share it: you see it even when they're far.",
  ["Lo comparten al momento quienes tienen el addon; del resto llega desde la web a través de la app puente."] = "Those who have the addon share it at once; for the rest it comes from the web through the bridge app.",
  ["Lo comparten los miembros con el addon; del resto, Battle.net a través de la web."] = "Members with the addon share it; for the rest, Battle.net through the web.",
  ["Lo decide el maestro. Ahora: %s"] = "The guild master decides. Now: %s",
  ["Lo decide su primer duelo: clic derecho en el retrato del otro, «Duelo»."] = "Their first duel decides it: right click on the other's portrait, «Duel».",
  ["Lo hace %s."] = "%s makes it.",
  ["Lo hago"] = "I'll make it",
  ["Lo lleva %s"] = "%s holds it",
  ["Lo pide %s. %s%s"] = "Asked by %s. %s%s",
  ["Lo puedes cambiar cuando quieras en la Armería."] = "You can change it whenever you want in the Armory.",
  ["Lo puedes quitar cuando quieras en la Armería («Compartir mi equipo»)."] = "You can turn it off whenever you want in the Armory («Share my gear»).",
  ["Lo que dice cualquiera en el chat de hermandad, tenga o no el addon. Lo que se dijo mientras no estabas te lo pasa un compañero con BlazonGuild."] = "What anyone says in the guild chat, with or without the addon. What was said while you were away is passed to you by a companion with BlazonGuild.",
  ["Lo que el propio juego dice de ti y cuenta para la hermandad: tus duelos con compañeros, quién te mata en JcJ fuera de mazmorras, el oro que das a un tesorero y los jefes que matáis juntos."] = "What the game itself reports about you that counts for the guild: your duels with guildmates, who kills you in PvP outside dungeons, the gold you give a treasurer and the bosses you kill together.",
  ["Lo que la hermandad debe saber"] = "What the guild should know",
  ["Lo que publicas lo ve tu hermandad: quién sabe hacer cada objeto, para susurrarte o hacerte un encargo. Se actualiza al abrir la profesión."] = "Your guild sees what you publish: who can make each item, to whisper you or place an order with you. It updates when you open the profession.",
  ["Lo que responde aquí"] = "What it answers here",
  ["Lo que tu hermandad publique desde el juego podrá verse también en la web de BlazonGuild."] = "What your guild publishes from the game can also be seen on the BlazonGuild website.",
  ["Lo que tú hagas desde el addon: apuntarte a una raid, publicar un grupo, tu perfil… Cada cosa la decides tú en el momento."] = "What you do from the addon: signing up for a raid, posting a group, your profile… You decide each thing at the moment.",
  ["Lo verás en la Armería en un momento."] = "You'll see it in the Armory in a moment.",
  ["Lo verás todo en /bg."] = "You'll see it all in /bg.",
  ["Lo vio el propio cliente de %s (el resumen de muerte del juego)."] = "Seen by %s's own client (the game's death recap).",
  ["Lo viste tú (%s)."] = "You saw it (%s).",
  ["Lo último"] = "Latest",
  ["Lo último: %s"] = "Latest: %s",
  ["Logros"] = "Achievements",
  ["Los Baldíos"] = "The Barrens",
  ["Los Humedales"] = "Wetlands",
  ["Los apuntados la verán como cancelada. Se puede volver a programar editándola."] = "The people signed up will see it as cancelled. It can be rescheduled by editing it.",
  ["Los cambios de la alianza van firmados: nadie puede falsificarlos."] = "Alliance changes are signed: nobody can forge them.",
  ["Los capitanes leen y escriben en «Oficiales de la alianza»; los mensajeros llevan los mensajes a las otras hermandades. Escribe su nombre y elige el cargo."] = "Captains read and write in «Alliance officers»; messengers carry the messages to the other guilds. Type their name and choose the role.",
  ["Los casos de moderación y los avisos ya solo están en el ordenador de los organizadores."] = "Moderation cases and warnings are now only on the organisers' computers.",
  ["Los combates de antes siguen guardados, pero ya no cuentan."] = "Earlier bouts are still kept, but they no longer count.",
  ["Los conectados de cada zona, tengan o no BlazonGuild."] = "Who's online in each zone, with or without BlazonGuild.",
  ["Los enlaces de objetos del chat se ven bien (antes salían rotos), también los ya guardados."] = "Item links in the chat show correctly (they used to be broken), the saved ones too.",
  ["Los grupos"] = "The groups",
  ["Los grupos se comparten entre los addons de tu hermandad. Acepta la privacidad para verlos (/bg privacidad)."] = "Groups are shared between your guild's addons. Accept the privacy to see them (/bg privacidad).",
  ["Los jefes de las bandas se apuntan aunque el juego dé solo el nombre, y la clasificación de hermandades ya verifica las fichas de las demás."] = "Raid bosses are recorded even when the game gives only the first name, and the guild ranking now verifies the other guilds' cards.",
  ["Los mueven el líder de la raid, quien la creó y los oficiales. Tú lo ves tal como está."] = "The raid leader, whoever created it and the officers move them. You see it as it is.",
  ["Los nombres y lo que escribe cada uno (notas, anuncios, mensajes) salen tal cual, sin traducir."] = "Names and what each person writes (notes, announcements, messages) appear as they are, untranslated.",
  ["Los oficiales apuntan a quién se dio cada objeto y por qué, para que la próxima banda empiece de lo ya decidido. Sin pujas ni oro."] = "The officers record who got each item and why, so the next raid starts from what was already decided. No bids, no gold.",
  ["Los oficiales crean escuadras pequeñas con su jefe (por ejemplo «Los Lobos», de asalto). El jefe elige a su gente; la escuadra tiene su propio chat."] = "The officers create small squads with their leader (for example «The Wolves», for assault). The leader picks their people; the squad has its own chat.",
  ["Los oficiales de %s ya la ven. Te invitarán desde el juego si dicen que sí."] = "%s's officers already see it. They'll invite you from the game if they say yes.",
  ["Los oficiales escriben la ficha pública: a qué os dedicáis, idioma, cuándo jugáis y a quién buscáis (por ejemplo, sanadores)."] = "The officers write the public card: what you do, language, when you play and who you're looking for (for example, healers).",
  ["Los organizadores de todas las hermandades de la alianza. Nadie más lo lee."] = "The organisers of all the alliance's guilds. Nobody else reads it.",
  ["Los organizadores nombran árbitros en la Arena. Un árbitro puede decidir a mano los combates de cualquier torneo y quitar un duelo apuntado por error."] = "The organisers name arbiters in the Arena. An arbiter can decide by hand the bouts of any tournament and remove a duel written down by mistake.",
  ["Los organizadores pueden ver el addon como un miembro («Ver como miembro»), y otros addons pueden leer BlazonGuild si tú les das permiso."] = "Organisers can see the addon as a member does («See as a member»), and other addons can read BlazonGuild if you allow them.",
  ["Los puntos de los compañeros en el mapa del mundo"] = "The guildmates' dots on the world map",
  ["Los puntos del minimapa y la flecha «Seguir»"] = "The minimap dots and the «Follow» arrow",
  ["Los que guardas valen %d."] = "The ones you keep are worth %d.",
  ["Los rankings"] = "The rankings",
  ["Los tesoreros"] = "The treasurers",
  ["Lotería de práctica"] = "Practice lottery",
  ["Lotería de práctica: cada día, hasta 3 boletos gratis; un oficial sortea con /roll 1-100 y se anuncia quién acierta."] = "Practice lottery: every day, up to 3 free tickets; an officer draws with /roll 1-100 and the winners are announced.",
  ["Lotería: ha salido el %s"] = "Lottery: the number is %s",
  ["Luchador 1"] = "Fighter 1",
  ["Luchador 2"] = "Fighter 2",
  ["Lugar: «%s»"] = "Place: «%s»",
  ["Líder: %s, maestro de %s."] = "Leader: %s, master of %s.",
  ["Maestro: %s. Aún sin contacto: llegará cuando se conecte alguien suyo con BlazonGuild."] = "Guild master: %s. No contact yet: it will come when someone of theirs logs in with BlazonGuild.",
  ["Maestros"] = "Masters",
  ["Mago"] = "Mage",
  ["Mano derecha"] = "Main hand",
