  ["Nueva sala"] = "New room",
  ["Nueva sección Alianza: une tu hermandad con otras (lo deciden los maestros)."] = "New Alliance section: join your guild with others (the masters decide).",
  ["Nueva sección Arena: duelos entre miembros con su clasificación. El resultado lo lee el propio juego."] = "New Arena section: duels between members with their ranking. The game itself reads the result.",
  ["Nueva sección Artesanía y botín: al abrir tu profesión, puedes publicarla para tu hermandad."] = "New Crafting and loot section: when you open your profession, you can publish it for your guild.",
  ["Nueva sección Chat: el chat de hermandad con más espacio y salas como Sanadores o Comercio."] = "New Chat section: the guild chat with more room and rooms like Healers or Trade.",
  ["Nueva sección Mapa: cuántos compañeros hay en cada zona y quiénes son."] = "New Map section: how many companions are in each zone and who they are.",
  ["Nueva sección Reclutamiento: la ficha pública de la hermandad, que escriben los oficiales."] = "New Recruitment section: the guild's public card, written by the officers.",
  ["Nueva sección Tablón: anuncios, encuestas, turnos de palabra, la crónica y el resumen de la semana."] = "New Board section: announcements, polls, speaking turns, the chronicle and the week's summary.",
  ["Nueva sección Tesorería: el libro de la hermandad se apunta solo cuando das oro a un tesorero (comercio o correo)."] = "New Treasury section: the guild ledger records itself when you give gold to a treasurer (trade or mail).",
  ["Nueva sección «Se busca»: quien de la otra facción mate a uno de los vuestros fuera de mazmorras entra en la lista con su recompensa."] = "New «Wanted» section: whoever of the other faction kills one of yours outside dungeons enters the list with their bounty.",
  ["Nueva temporada"] = "New season",
  ["Nuevo"] = "New",
  ["Nuevo JcE: quién tiene nivel para cada banda, los jefes que lleva derrotados la hermandad (se apuntan solos) y las últimas raids."] = "New PvE: who has the level for each raid, the bosses the guild has defeated (written down by themselves) and the last raids.",
  ["Nuevo anuncio"] = "New announcement",
  ["Nuevo botón redondo en el minimapa: un clic abre o cierra BlazonGuild; arrástralo para moverlo."] = "New round button on the minimap: one click opens or closes BlazonGuild; drag it to move it.",
  ["Nuevo botón «?» arriba: «Cómo funciona», una guía corta y con ejemplos de cada sección complicada."] = "New «?» button at the top: «How it works», a short guide with examples for each complicated section.",
  ["Nuevo encargo"] = "New order",
  ["Nuevo honor en Rankings: Campeón de la Arena. Y arreglado: algunos botones salían sin texto."] = "New honour in Rankings: Arena champion. And fixed: some buttons showed no text.",
  ["Nuevo líder de la alianza"] = "New alliance leader",
  ["Nuevo torneo o velada"] = "New tournament or fight night",
  ["Nunca se comparten tu BattleTag ni tu posición en el mapa sin que lo aceptes aparte, una cosa cada vez. Si no aceptas, el addon te sigue mostrando tu hermandad, pero no envía nada."] = "Your BattleTag and your position on the map are never shared unless you accept them separately, one thing at a time. If you don't accept, the addon still shows you your guild, but sends nothing.",
  ["Nunca se comparten tu posición en el mapa, tu equipo, tus otros personajes, tu BattleTag ni dónde ves a enemigos sin que lo aceptes aparte, una cosa cada vez. Si no aceptas, el addon te sigue mostrando tu hermandad, pero no envía nada."] = "Your position on the map, your gear, your other characters, your BattleTag and where you see enemies are never shared unless you agree separately, one thing at a time. If you don't accept, the addon still shows you your guild, but sends nothing.",
  ["Nunca se han enfrentado"] = "Never met",
