  ["Te toca: tira %d %s"] = "Your turn: throw %d %s",
  ["Te trajo: %s. Puedes cambiarlo."] = "Brought by: %s. You can change it.",
  ["Templo de Ahn'Qiraj"] = "Temple of Ahn'Qiraj",
  ["Templo de Atal'Hakkar"] = "The Temple of Atal'Hakkar",
  ["Temporada %s"] = "Season %s",
  ["Temporada %s%s: %s%s"] = "Season %s%s: %s%s",
  ["Temporada %s: campeón %s%s."] = "Season %s: champion %s%s.",
  ["Tendréis un chat común, con una pestaña para cada hermandad."] = "You'll have a shared chat, with a tab for each guild.",
  ["Tenías una ficha en %s (tu presentación, tu rol, cuándo juegas)."] = "You had a card in %s (your introduction, your role, when you play).",
  ["Tercer aviso: %s"] = "Third warning: %s",
  ["Termina antes tu partida."] = "Finish your game first.",
  ["Terminada"] = "Finished",
  ["Terminado"] = "Finished",
  ["Terminar"] = "Finish",
  ["Terminar y guardar el parte"] = "Finish and save the report",
  ["Tesoreros (nombres separados por comas)"] = "Treasurers (names separated by commas)",
  ["Tesoreros: %s. "] = "Treasurers: %s. ",
  ["Tesorería"] = "Treasury",
  ["Tesorería: el oro se escribe también como 2g 50s. Autoprueba: dice cómo escribe tu juego los nombres."] = "Treasury: gold can also be typed as 2g 50s. Self-test: it says how your game writes names.",
  ["Tesorería: las cantidades ya caben en sus cuadros. Rankings: los 10 primeros de cada honor, y ya no está el del nivel 60."] = "Treasury: the amounts now fit in their boxes. Rankings: the top 10 of each honour, and the level 60 one is gone.",
  ["Texto (opcional)"] = "Text (optional)",
  ["The Barrow Deeps"] = "The Barrow Deeps",
  ["Tiene que estar cerca de ti (tu objetivo, el ratón encima o en tu grupo)."] = "They must be near you (your target, under the mouse or in your group).",
  ["Tiene que estar conectado y con BlazonGuild."] = "They have to be online and have BlazonGuild.",
  ["Tienes la palabra"] = "You have the floor",
  ["Tienes que ser líder o ayudante de la banda."] = "You have to be raid leader or assistant.",
  ["Tierras Inhóspitas"] = "Badlands",
  ["Tierras de la Peste del Este"] = "Eastern Plaguelands",
  ["Tierras de la Peste del Oeste"] = "Western Plaguelands",
  ["Tipo %s"] = "Kind %s",
  ["Tira los dados."] = "Throw the dice.",
  ["Tira los que quedan, o plántate y súmalo."] = "Throw the rest, or stand and add it up.",
  ["Tira seis dados, aparta los que puntúan y decide: arriesgar con el resto o plantarte. Si una tirada no da nada, pierdes lo del turno. Gana quien llega a %s. Los dados salen del /roll del juego."] = "Throw six dice, set aside those that score and decide: risk the rest or stand. If a throw gives nothing, you lose the turn's points. First to %s wins. The dice come from the game's /roll.",
  ["Tirando…"] = "Rolling…",
  ["Tirar"] = "Throw",
  ["Tirar %d %s"] = "Throw %d %s",
  ["Tirar %s%s"] = "Throw %s%s",
  ["Toda la alianza"] = "Whole alliance",
  ["Toda la alianza, de «%s»"] = "The whole alliance, from «%s»",
  ["Toda la hermandad"] = "Whole guild",
  ["Todavía no ha escrito nada sobre sí."] = "Hasn't written anything about themselves yet.",
  ["Todavía no has escrito nada. Pulsa «Editar mi ficha»."] = "You haven't written anything yet. Press «Edit my card».",
  ["Todavía no hay mensajes en esta sesión. Lo que se diga en el chat de hermandad aparecerá aquí."] = "No messages this session yet. What's said in the guild chat will show here.",
  ["Todavía no hay raids programadas en %s."] = "No raids scheduled in %s yet.",
  ["Todos"] = "Everyone",
  ["Todos empiezan con %s puntos. Ganar a alguien mejor que tú da más puntos; a alguien de más nivel, también."] = "Everyone starts with %s points. Beating someone better than you gives more points; someone of higher level, too.",
  ["Todos empiezan con 1500. Ganar a alguien mejor da más puntos. Por ejemplo, en tus primeros combates y con el mismo nivel: ganar a uno de 1600 da unos 26; a uno de 1400, unos 14."] = "Everyone starts with 1500. Beating someone better gives more points. For example, in your first bouts and at the same level: beating someone with 1600 gives about 26; someone with 1400, about 14.",
  ["Todos empiezan de cero. ¡Suerte!"] = "Everyone starts from zero. Good luck!",
  ["Todos los apuntados tienen grupo."] = "Everyone signed up has a group.",
  ["Todos los mensajes de la alianza llevan una marca hecha con su clave. Cámbiala si crees que la conoce alguien de fuera."] = "All the alliance's messages carry a mark made with its key. Change it if you think someone outside knows it.",
  ["Todos ven los grupos; los mueven el líder de la raid, quien la creó y los oficiales."] = "Everyone sees the groups; the raid leader, whoever created it and the officers move them.",
  ["Todos vuelven a empezar con %s puntos."] = "Everyone starts again with %s points.",
  ["Torneo"] = "Tournament",
  ["Torneo, %s"] = "Tournament, %s",
  ["Torneo: %s"] = "Tournament: %s",
  ["Torneo: cada uno se apunta; al sortear sale el cuadro eliminatorio."] = "Tournament: each one signs up; when drawn, the knockout bracket appears.",
  ["Torneos"] = "Tournaments",
  ["Torneos y veladas"] = "Tournaments and fight nights",
  ["Traerla"] = "Bring it",
  ["Tres iguales: la cara × 100 (tres 4 = 400); tres 1 = 1000. Cada dado igual de más lo dobla."] = "Three of a kind: the face × 100 (three 4s = 400); three 1s = 1000. Each extra matching die doubles it.",
  ["Tu addon apunta solo lo tuyo, con el resumen de muerte y tu golpe final."] = "Your addon records only your own, with the death recap and your killing blow.",
  ["Tu bandera en el tablón"] = "Your flag on the board",
  ["Tu equipo y su nivel"] = "Your gear and its level",
  ["Tu ficha"] = "Your card",
  ["Tu firma aún no está en la alianza. La añade vuestro maestro la próxima vez que se conecte."] = "Your signature isn't in the alliance yet. Your guild master adds it the next time they log in.",
  ["Tu grupo"] = "Your group",
  ["Tu grupo: %s"] = "Your group: %s",
  ["Tu hermandad"] = "Your guild",
  ["Tu hermandad dejará de ver el chat de la alianza y sus salas compartidas. Las demás hermandades siguen juntas."] = "Your guild will stop seeing the alliance chat and its shared rooms. The other guilds stay together.",
  ["Tu hermandad ve lo que llevas puesto en la Armería; se actualiza cuando cambias algo."] = "Your guild sees what you wear in the Armory; it updates when you change something.",
  ["Tu hermandad verá en «Artesanía y botín» lo que sabes fabricar de %s (%s/%s)."] = "Your guild will see in «Crafting and loot» what you can make with %s (%s/%s).",
  ["Tu inscripción"] = "Your sign-up",
  ["Tu mensaje volvió en %d ms. Ningún otro miembro conectado tiene BlazonGuild ahora."] = "Your message came back in %d ms. No other online member has BlazonGuild right now.",
  ["Tu nuevo rango, %s, es de organizador en BlazonGuild. A partir de ahora puedes:"] = "Your new rank, %s, is an organiser rank in BlazonGuild. From now on you can:",
